package com.centralplay.app.ui;

import android.content.Intent;import android.os.Bundle;import android.view.*;import androidx.appcompat.app.AppCompatActivity;import androidx.appcompat.widget.SearchView;import androidx.core.splashscreen.SplashScreen;import androidx.fragment.app.Fragment;import com.centralplay.app.R;import com.centralplay.app.data.CatalogRepository;import com.google.android.material.appbar.MaterialToolbar;import com.google.android.material.bottomnavigation.BottomNavigationView;
public class MainActivity extends AppCompatActivity {private MaterialToolbar toolbar;private Fragment current;@Override protected void onCreate(Bundle b){SplashScreen.installSplashScreen(this);super.onCreate(b);setContentView(R.layout.activity_main);toolbar=findViewById(R.id.toolbar);setSupportActionBar(toolbar);BottomNavigationView nav=findViewById(R.id.bottom_nav);nav.setOnItemSelectedListener(i->{int id=i.getItemId();if(id==R.id.nav_home)show("home");else if(id==R.id.nav_live)show("live");else if(id==R.id.nav_movies)show("movie");else if(id==R.id.nav_series)show("series");else if(id==R.id.nav_favorites)show("favorites");return true;});if(b==null){nav.setSelectedItemId(R.id.nav_home);sync(false);}}private void show(String mode){current="home".equals(mode)?new HomeFragment():ContentListFragment.newInstance(mode);getSupportFragmentManager().beginTransaction().replace(R.id.fragment_container,current).commit();toolbar.setTitle("home".equals(mode)?"Central Play":label(mode));}private String label(String m){switch(m){case"live":return"TV en vivo";case"movie":return"Películas";case"series":return"Series";case"favorites":return"Favoritos";default:return"Central Play";}}@Override public boolean onCreateOptionsMenu(Menu menu){getMenuInflater().inflate(R.menu.menu_main,menu);MenuItem item=menu.findItem(R.id.action_search);SearchView sv=(SearchView)item.getActionView();if(sv!=null)sv.setOnQueryTextListener(new SearchView.OnQueryTextListener(){public boolean onQueryTextSubmit(String q){setQuery(q);return true;}public boolean onQueryTextChange(String q){setQuery(q);return true;}});return true;}private void setQuery(String q){if(current instanceof Searchable)((Searchable)current).setQuery(q);}@Override public boolean onOptionsItemSelected(MenuItem item){if(item.getItemId()==R.id.action_refresh){sync(true);return true;}if(item.getItemId()==R.id.action_settings){startActivity(new Intent(this,SettingsActivity.class));return true;}return super.onOptionsItemSelected(item);}private void sync(boolean toast){CatalogRepository.get(this).refreshAsync((c,s,e)->{if(toast)android.widget.Toast.makeText(this,e.trim().isEmpty()?"Catálogo actualizado":"Usando "+s+" · "+e,android.widget.Toast.LENGTH_LONG).show();if(current instanceof HomeFragment)((HomeFragment)current).refresh();if(current instanceof ContentListFragment)((ContentListFragment)current).reload();AppUpdateChecker.check(this,c);});}}
